mapper.select:
SELECT DISTINCT ON (knowledge_point) knowledge_point AS knowledgePoint,
       error_type AS errorType, created_at AS createdAt
FROM weakness_record
WHERE tenant_id = #{tenantId}::uuid AND student_id = #{studentId}
ORDER BY knowledge_point, created_at DESC
LIMIT #{limit}

SELECT student_id AS studentId, knowledge_point AS knowledgePoint, error_type AS errorType,
       strength, evidence_count AS evidenceCount, first_seen_at AS firstSeenAt,
       last_seen_at AS lastSeenAt, last_run_id AS lastRunId
FROM student_memory
WHERE tenant_id = #{tenantId}::uuid AND student_id = #{studentId}
  AND knowledge_point = #{knowledgePoint}

mapper.update:
UPDATE student_memory SET error_type = #{errorType}, strength = #{strength},
       evidence_count = #{evidenceCount}, last_seen_at = #{lastSeenAt},
       last_run_id = #{lastRunId}::uuid, updated_at = now()
WHERE tenant_id = #{tenantId}::uuid AND student_id = #{studentId}
  AND knowledge_point = #{knowledgePoint}
